  -- perfsand beginner final - ord 40
  select case when md5(prompt) = 'b0d28dfc7ed1c1e60dc494f91286fb9d' and md5(coalesce(explanation, '')) = 'e01f48c85dd305123438b93a45393bd9' and md5(options::text) = md5('["The phasing angle of the gun as run.", "The tunnel length, because the concrete-to-rock correction changes with the rock.", "The shot density, since a harder rock absorbs more of the charge energy.", "The wellbore radius, which the bit size through the interval sets."]'::jsonb::text) and answer_index = 1 then 'old'
              when md5(prompt) = 'b0d28dfc7ed1c1e60dc494f91286fb9d' and md5(coalesce(explanation, '')) = '06a57b1931793cd9e62a4160435803c2' and md5(options::text) = md5('["The phasing angle of the gun as run.", "The tunnel length, because the concrete-to-rock correction changes with the rock.", "The shot density, since a harder rock absorbs more of the charge energy.", "The wellbore radius, which the bit size through the interval sets."]'::jsonb::text) and answer_index = 1 then 'new'
              else 'other' end
