  if v_state is null then raise exception 'B4 fix perfsand refused: no row for perfsand beginner final - ord 40'; end if;
  if v_state = 'other' then raise exception 'B4 fix perfsand refused: perfsand beginner final - ord 40 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'The same gun is run in a different rock. Which output changes?', options = '["The phasing angle of the gun as run.", "The tunnel length, because the concrete-to-rock correction changes with the rock.", "The shot density, since a harder rock absorbs more of the charge energy.", "The wellbore radius, which the bit size through the interval sets."]'::jsonb,
           answer_index = 1, explanation = 'The catalog row is unchanged, but what the rock does to the penetration is not: formation penetration is generally less than the concrete figure, and it depends on the rock strength and the effective stress. This engine applies no such correction and takes the penetration it is given, so making it is your job.'
