  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'The same gun is run in a different rock, and the engine is given the same tunnel length. Which skin term would you expect to change?', options = '["The plane-flow term, through the effective wellbore radius it reads.", "The wellbore blockage term, since the blockage ratio depends on the tunnel length relative to the wellbore radius.", "The converging-flow term, through the permeability anisotropy.", "Nothing at all, because a perforation skin is a geometric quantity and no rock property enters it anywhere."]'::jsonb,
